        const baseS = new mu();
        const hw2 = bw / 2 - 0.012, hd2 = bd2 / 2 - 0.012, rc2 = 0.1;
        baseS.moveTo(-hw2 + rc2, -hd2);
        baseS.lineTo(hw2 - rc2, -hd2);
        baseS.absarc(hw2 - rc2, -hd2 + rc2, rc2, -Math.PI / 2, 0, false);
        baseS.lineTo(hw2, hd2 - rc2);
        baseS.absarc(hw2 - rc2, hd2 - rc2, rc2, 0, Math.PI / 2, false);
        baseS.lineTo(-hw2 + rc2, hd2);
        baseS.absarc(-hw2 + rc2, hd2 - rc2, rc2, Math.PI / 2, Math.PI, false);
        baseS.lineTo(-hw2, -hd2 + rc2);
