        baseS.closePath();
        for (const [hx, hz] of holeAt) {
          const p2 = new eu();
          p2.absarc(hx, hz, HOLE_R, 0, Math.PI * 2, true);
          baseS.holes.push(p2);
        }
        const slab = extrudeY(baseS, slabH);
