    const key2 = touch ? "" : ' \xB7 <span class="r">R</span> \u65CB\u8F6C';
    const spins = [];
    if (state.ry) spins.push(`\u8F6C\u5411 ${state.ry * 90}\xB0`);
    if (state.rx) spins.push(`\u4FEF\u4EF0 ${state.rx * 90}\xB0`);
    if (state.rz) spins.push(`\u6447\u6446 ${state.rz * 90}\xB0`);
